+
+  it("is hidden from assistive technology", () => {
+    const { container } = render(<OdiMascot />);
+    expect(container.querySelector("svg")?.getAttribute("aria-hidden")).toBe("true");
+    expect(screen.queryByRole("img")).toBeNull();
+  });
