   align-items: center;
   gap: 8px;
   min-width: 0;
 }

 .bar__brand {
   padding: 4px 8px;
   border: 0;
   border-radius: 8px;
   background: transparent;
   font: inherit;
   font-size: 0.8rem;
   color: var(--muted);
   white-space: nowrap;
