   padding: 5px 11px;
   border: 1px solid var(--line);
   border-radius: 999px;
   background: transparent;
   color: var(--faint);
   font-size: 0.72rem;
   cursor: pointer;
 }

 .bar__health:hover {
   color: var(--muted);
   border-color: var(--line-strong);
 }

