===================================================================
--- website/dist/assets/style.css	
+++ website/dist/assets/style.css	
@@ -1,1804 +1,2276 @@
 /* =====================================================================
    Agentic ODI — the site design system.

    Colours, radii, and easings live in assets/tokens.css, generated from
    the Living Studio's own theme so the site and the product are the same
    visual language. This file holds layout, type, components, and motion.

    Rule: no hex colour here. Everything is a var(--…) reference.
    ===================================================================== */

 /* ---------------------------------------------------------------- */
 /* Reset                                                            */
 /* ---------------------------------------------------------------- */

 *,
 *::before,
 *::after {
   box-sizing: border-box;
 }

 html {
   -webkit-text-size-adjust: 100%;
   scroll-behavior: smooth;
   scroll-padding-top: 96px;
 }

 body,
 h1, h2, h3, h4, p, figure, blockquote, dl, dd, ul, ol {
   margin: 0;
 }

 ul[class], ol[class] {
   list-style: none;
   padding: 0;
 }

 img, svg, video {
   display: block;
   max-width: 100%;
 }

 button, input, select, textarea {
   font: inherit;
   color: inherit;
 }

 button {
   cursor: pointer;
   border: 0;
   background: none;
 }

 a {
   color: var(--accent);
   text-decoration: none;
 }

 a:hover {
   color: var(--text);
 }

 :focus-visible {
   outline: 2px solid var(--accent);
   outline-offset: 3px;
   border-radius: 4px;
 }

 ::selection {
   background: var(--accent-strong);
   color: var(--text);
 }

 /* ---------------------------------------------------------------- */
 /* Base                                                             */
 /* ---------------------------------------------------------------- */

 body {
   min-height: 100vh;
   background: var(--bg);
   color: var(--text);
   font-family: var(--font);
   font-size: 1.0625rem;
   line-height: 1.65;
   -webkit-font-smoothing: antialiased;
   -moz-osx-font-smoothing: grayscale;
   overflow-x: hidden;
 }

 /* The canvas. The Studio's own two radial washes — depth without imagery. */
 body::before {
   content: "";
   position: fixed;
   inset: 0;
   z-index: -1;
   pointer-events: none;
   background:
     radial-gradient(
       760px 420px at 50% 108%,
       color-mix(in srgb, var(--accent-strong) 9%, transparent),
       transparent 72%
     ),
     radial-gradient(
       900px 520px at 68% -12%,
       color-mix(in srgb, var(--accent-strong) 8%, transparent),
       transparent 68%
     );
 }

 .skip-link {
   position: absolute;
   left: 16px;
   top: -60px;
   z-index: 100;
   padding: 10px 16px;
   border-radius: var(--r-md);
   background: var(--accent);
   color: var(--accent-ink);
   font-size: 0.875rem;
   font-weight: 600;
   transition: top 0.15s var(--ease-tactile);
 }

 .skip-link:focus {
   top: 16px;
   color: var(--accent-ink);
 }

 .sr-only {
   position: absolute;
   width: 1px;
   height: 1px;
   padding: 0;
   margin: -1px;
   overflow: hidden;
   clip: rect(0, 0, 0, 0);
   white-space: nowrap;
   border: 0;
 }

 /* ---------------------------------------------------------------- */
 /* Type scale                                                       */
 /* ---------------------------------------------------------------- */

 .eyebrow {
   display: inline-flex;
   align-items: center;
   gap: 8px;
   margin: 0 0 20px;
   font-size: 0.6875rem;
   font-weight: 600;
   letter-spacing: 0.18em;
   text-transform: uppercase;
   color: var(--faint);
 }

 .eyebrow--pill {
   padding: 6px 14px;
   border: 1px solid var(--line-strong);
   border-radius: var(--r-pill);
   background: var(--surface);
   color: var(--muted);
 }

 .display {
   text-wrap: balance;
   font-size: clamp(2.75rem, 7.5vw, 6rem);
   font-weight: 600;
   letter-spacing: -0.04em;
   line-height: 0.98;
 }

 .section__title {
   max-width: 20ch;
   text-wrap: balance;
   font-size: clamp(1.875rem, 4vw, 3.25rem);
   font-weight: 600;
   letter-spacing: -0.03em;
   line-height: 1.06;
 }

 .section__title--wide {
   max-width: 28ch;
 }

 .lead {
   max-width: 52ch;
   font-size: clamp(1.0625rem, 1.5vw, 1.375rem);
   line-height: 1.5;
   color: var(--muted);
 }

 .prose {
   max-width: var(--w-prose);
   color: var(--muted);
 }

 .prose > * + * {
   margin-top: 1.15em;
 }

 .prose strong {
   color: var(--text);
   font-weight: 600;
 }

 .prose a {
   text-decoration: underline;
   text-underline-offset: 3px;
   text-decoration-thickness: 1px;
 }

 .prose code {
   padding: 1px 5px;
   border-radius: 5px;
   background: var(--surface);
   color: var(--text);
   font-family: var(--mono);
   font-size: 0.85em;
 }

 .prose h2 {
   margin-top: 2.2em;
   font-size: 1.5rem;
   font-weight: 600;
   letter-spacing: -0.02em;
   color: var(--text);
 }

 .prose h3 {
   margin-top: 1.8em;
   font-size: 1.125rem;
   font-weight: 600;
   letter-spacing: -0.01em;
   color: var(--text);
 }

 .prose ul, .prose ol {
   padding-left: 1.25em;
 }

 .prose li + li {
   margin-top: 0.4em;
 }

 .prose blockquote {
   padding-left: 1em;
   border-left: 2px solid var(--line-strong);
   color: var(--muted);
   font-style: italic;
 }

 .prose table {
   width: 100%;
   border-collapse: collapse;
   font-size: 0.9375rem;
 }

 .prose th, .prose td {
   padding: 10px 14px;
   border-bottom: 1px solid var(--line);
   text-align: left;
   vertical-align: top;
 }

 .prose th {
   color: var(--text);
   font-size: 0.6875rem;
   font-weight: 600;
   letter-spacing: 0.09em;
   text-transform: uppercase;
   color: var(--faint);
 }

 .label {
   font-size: 0.6875rem;
   font-weight: 600;
   letter-spacing: 0.1em;
   text-transform: uppercase;
   color: var(--faint);
 }

 .mono {
   font-family: var(--mono);
 }

 /* ---------------------------------------------------------------- */
 /* Layout                                                           */
 /* ---------------------------------------------------------------- */

 .shell {
   width: 100%;
   max-width: var(--w-page);
   margin-inline: auto;
   padding-inline: var(--gutter);
 }

 .shell--wide {
   max-width: var(--w-wide);
 }

 .section {
   padding-block: var(--section-y);
 }

 .section + .section {
   border-top: 1px solid var(--line);
 }

 .section__head {
   display: flex;
   flex-direction: column;
   gap: 20px;
   margin-bottom: clamp(40px, 6vw, 72px);
 }

 .grid {
   display: grid;
   gap: 20px;
 }

 .grid--2 { grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); }
 .grid--3 { grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); }
 .grid--4 { grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); }

 .stack {
   display: flex;
   flex-direction: column;
   gap: 16px;
 }

 .cluster {
   display: flex;
   flex-wrap: wrap;
   gap: 10px;
   align-items: center;
 }

 /* ---------------------------------------------------------------- */
 /* Header & footer                                                  */
 /* ---------------------------------------------------------------- */

 .site-header {
   position: sticky;
   top: 0;
   z-index: 50;
   border-bottom: 1px solid var(--line);
   background: color-mix(in srgb, var(--bg) 72%, transparent);
   backdrop-filter: blur(16px) saturate(180%);
   -webkit-backdrop-filter: blur(16px) saturate(180%);
 }

 .site-header__inner {
   display: flex;
   align-items: center;
   justify-content: space-between;
   gap: 20px;
   width: 100%;
   max-width: var(--w-page);
   margin-inline: auto;
   padding: 14px var(--gutter);
 }

 .brand {
   display: inline-flex;
   align-items: center;
   gap: 10px;
   color: var(--text);
 }

 .brand:hover { color: var(--text); }

 .brand__name {
   font-size: 0.9375rem;
   font-weight: 600;
   letter-spacing: -0.01em;
 }

 .site-nav {
   display: flex;
   gap: 24px;
   font-size: 0.875rem;
   color: var(--muted);
 }

 .site-nav a:hover {
   color: var(--text);
 }

 .site-footer {
   border-top: 1px solid var(--line);
   padding-block: clamp(48px, 7vw, 88px);
   color: var(--faint);
   font-size: 0.875rem;
 }

 .site-footer__top {
   display: flex;
   flex-wrap: wrap;
   align-items: baseline;
   justify-content: space-between;
   gap: 12px 24px;
   margin-bottom: 28px;
 }

 .site-footer__brand {
   display: inline-flex;
   align-items: center;
   gap: 10px;
   color: var(--text);
 }

 .site-footer__tagline {
   color: var(--muted);
 }

 .site-footer__nav {
   display: flex;
   flex-wrap: wrap;
   gap: 8px 24px;
   margin-bottom: 28px;
 }

 .site-footer__nav a {
   color: var(--muted);
 }

 .site-footer__nav a:hover {
   color: var(--text);
 }

 .site-footer__legal {
   color: var(--faint);
 }

 .site-footer__note {
   margin-top: 6px;
   color: var(--faint);
 }

 /* ---------------------------------------------------------------- */
 /* Buttons, pills, cards                                            */
 /* ---------------------------------------------------------------- */

 .btn {
   display: inline-flex;
   align-items: center;
   justify-content: center;
   gap: 8px;
   padding: 13px 24px;
   border: 1px solid transparent;
   border-radius: var(--r-pill);
   font-size: 0.9375rem;
   font-weight: 600;
   letter-spacing: -0.01em;
   transition:
     transform 0.15s var(--ease-tactile),
     background-color 0.15s var(--ease-tactile),
     border-color 0.15s var(--ease-tactile),
     opacity 0.15s var(--ease-tactile);
 }

 .btn--primary {
   background: var(--accent);
   color: var(--accent-ink);
 }

 .btn--primary:hover {
   color: var(--accent-ink);
   transform: translateY(-1px);
   opacity: 0.92;
 }

 .btn--ghost {
   border-color: var(--line-strong);
   background: var(--surface);
   color: var(--text);
 }

 .btn--ghost:hover {
   color: var(--text);
   transform: translateY(-1px);
   background: var(--surface-hover);
 }

 .btn--sm {
   padding: 9px 18px;
   font-size: 0.875rem;
 }

 .btn:active {
   transform: scale(0.98);
 }

 .pill {
   display: inline-flex;
   align-items: center;
   gap: 6px;
   padding: 3px 10px;
   border: 1px solid var(--line-strong);
   border-radius: var(--r-pill);
   font-size: 0.6875rem;
   font-weight: 600;
   letter-spacing: 0.06em;
   text-transform: uppercase;
   color: var(--muted);
   white-space: nowrap;
 }

 .pill--accent {
   border-color: color-mix(in srgb, var(--accent) 34%, transparent);
   background: color-mix(in srgb, var(--accent) 12%, transparent);
   color: var(--accent);
 }

 .pill--positive {
   border-color: color-mix(in srgb, var(--green) 28%, transparent);
   background: color-mix(in srgb, var(--green) 10%, transparent);
   color: var(--green);
 }

 .pill--warning {
   border-color: color-mix(in srgb, var(--amber) 30%, transparent);
   background: color-mix(in srgb, var(--amber) 10%, transparent);
   color: var(--amber);
 }

 .card {
   padding: 24px;
   border: 1px solid var(--line);
   border-radius: var(--r-lg);
   background: var(--surface);
   transition:
     transform 0.2s var(--ease-apple-out),
     border-color 0.2s var(--ease-apple-out),
     background-color 0.2s var(--ease-apple-out);
 }

 .card:hover {
   transform: translateY(-2px);
   border-color: var(--line-strong);
   background: var(--surface-hover);
 }

 .card__title {
   font-size: 1.0625rem;
   font-weight: 600;
   letter-spacing: -0.01em;
 }

 .card__body {
   margin-top: 10px;
   color: var(--muted);
   font-size: 0.9375rem;
   line-height: 1.6;
 }

 .glass {
   border: 1px solid var(--line-strong);
   border-radius: var(--r-lg);
   background: var(--glass);
   backdrop-filter: var(--glass-blur);
   -webkit-backdrop-filter: var(--glass-blur);
   box-shadow: var(--hairline), 0 40px 120px -20px rgba(0, 0, 0, 0.85);
 }

 /* ---------------------------------------------------------------- */
 /* Hero                                                             */
 /* ---------------------------------------------------------------- */

 .hero {
   display: flex;
   align-items: center;
   min-height: calc(100svh - 68px);
   padding-block: clamp(72px, 11vw, 140px);
   text-align: center;
 }

 .hero__inner {
   display: flex;
   flex-direction: column;
   align-items: center;
   gap: 24px;
 }

 .hero__title {
   max-width: 20ch;
   text-wrap: balance;
   font-size: clamp(2.75rem, 7.5vw, 6rem);
   font-weight: 600;
   letter-spacing: -0.04em;
   line-height: 0.98;
 }

 .hero__sub {
   max-width: 46ch;
   color: var(--muted);
   font-size: clamp(1.0625rem, 1.6vw, 1.375rem);
   line-height: 1.5;
 }

 .hero__actions {
   display: flex;
   flex-wrap: wrap;
   justify-content: center;
   gap: 12px;
   margin-top: 8px;
 }

 .hero__cue {
   display: inline-flex;
   align-items: center;
   gap: 8px;
   margin-top: 12px;
   color: var(--faint);
   font-size: 0.8125rem;
 }

 .hero__cue span {
   display: block;
   width: 1px;
   height: 22px;
   background: linear-gradient(to bottom, var(--line-strong), transparent);
 }

 /* ---------------------------------------------------------------- */
 /* Problem                                                          */
 /* ---------------------------------------------------------------- */

 .beats {
   display: grid;
   gap: 20px;
   grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
 }

 .beat {
   display: flex;
   flex-direction: column;
   gap: 12px;
   padding: 26px;
   border: 1px solid var(--line);
   border-radius: var(--r-lg);
   background: var(--surface);
 }

 .beat__quote {
   font-size: 1.125rem;
   font-weight: 600;
   letter-spacing: -0.01em;
   line-height: 1.35;
 }

 .beat__support {
   color: var(--muted);
   font-size: 0.9375rem;
   line-height: 1.6;
 }

 .closer {
   margin-top: 40px;
   max-width: 34ch;
   font-size: clamp(1.375rem, 2.4vw, 2rem);
   font-weight: 600;
   letter-spacing: -0.025em;
   line-height: 1.2;
   color: var(--text);
 }

 /* ---------------------------------------------------------------- */
 /* Insight — the formula                                            */
 /* ---------------------------------------------------------------- */

 .insight {
   display: grid;
   gap: clamp(40px, 6vw, 72px);
   grid-template-columns: minmax(0, 1fr);
   align-items: start;
 }

 @media (min-width: 960px) {
   .insight {
     grid-template-columns: minmax(0, 1.15fr) minmax(0, 0.85fr);
   }
 }

 .formula {
   display: flex;
   flex-wrap: wrap;
   align-items: baseline;
   gap: 10px;
   overflow-x: auto;
   padding: 22px 24px;
   border: 1px solid var(--line);
   border-radius: var(--r-md);
   background: var(--bg-sunken);
   font-family: var(--mono);
   font-size: clamp(0.875rem, 1.35vw, 1rem);
   line-height: 1.5;
 }

 .formula__label {
   color: var(--muted);
 }

 .formula__expr {
   color: var(--text);
   white-space: nowrap;
 }

 .formula__gap {
   color: var(--accent);
 }

 .statline {
   display: flex;
   flex-wrap: wrap;
   align-items: baseline;
   gap: 8px 12px;
   margin-top: 20px;
   font-size: 0.9375rem;
 }

 .statline__value {
   font-size: 1.125rem;
   font-weight: 600;
   letter-spacing: -0.01em;
 }

 .statline__source {
   color: var(--faint);
 }

 /* The importance/satisfaction gap, drawn honestly. */
 .gap {
   display: flex;
   flex-direction: column;
   gap: 14px;
   padding: 24px;
   border: 1px solid var(--line);
   border-radius: var(--r-lg);
   background: var(--surface);
 }

 .gap__row {
   display: grid;
   grid-template-columns: 96px 1fr 40px;
   align-items: center;
   gap: 14px;
   font-size: 0.8125rem;
   color: var(--muted);
 }

 .gap__track {
   display: block;
   height: 8px;
   border-radius: var(--r-pill);
   background: var(--surface-hover);
   overflow: hidden;
 }

 .gap__fill {
   display: block;
   height: 100%;
   border-radius: var(--r-pill);
   background: var(--accent-strong);
 }

 .gap__fill--satisfaction {
   background: color-mix(in srgb, var(--muted) 55%, transparent);
 }

 .gap__value {
   font-family: var(--mono);
   font-size: 0.8125rem;
   text-align: right;
   color: var(--text);
 }

 .gap__note {
   color: var(--faint);
   font-size: 0.8125rem;
   line-height: 1.5;
 }

 /* ---------------------------------------------------------------- */
 /* The demo — the Living Studio, running its script                  */
 /* ---------------------------------------------------------------- */

 .demo {
   display: flex;
   flex-direction: column;
   gap: 18px;
 }

 .demo__notice {
   display: flex;
   flex-wrap: wrap;
   align-items: center;
   gap: 10px 16px;
 }

 .demo__label {
   display: inline-flex;
   align-items: center;
   padding: 4px 12px;
   border: 1px solid color-mix(in srgb, var(--amber) 32%, transparent);
   border-radius: var(--r-pill);
   background: color-mix(in srgb, var(--amber) 10%, transparent);
   color: var(--amber);
   font-size: 0.6875rem;
   font-weight: 600;
   letter-spacing: 0.1em;
   text-transform: uppercase;
   white-space: nowrap;
 }

 .demo__disclaimer {
   color: var(--faint);
   font-size: 0.875rem;
   line-height: 1.5;
 }

 .demo__disclaimer a {
   color: var(--muted);
   text-decoration: underline;
   text-underline-offset: 3px;
 }

 .demo__disclaimer a:hover {
   color: var(--text);
 }

 .demo__frame {
   overflow: hidden;
   border-radius: var(--r-lg);
   background: var(--bg-raised);
 }

 .demo__bar {
   display: flex;
   align-items: center;
   justify-content: space-between;
   gap: 12px;
   height: 46px;
   padding: 0 16px;
   border-bottom: 1px solid var(--line);
 }

 .demo__brand {
   display: inline-flex;
   align-items: center;
   gap: 9px;
   font-size: 0.8125rem;
   font-weight: 600;
   letter-spacing: -0.01em;
 }

 .demo__health {
   display: inline-flex;
   align-items: center;
   gap: 7px;
   padding: 4px 11px;
   border: 1px solid var(--line);
   border-radius: var(--r-pill);
   color: var(--faint);
   font-size: 0.6875rem;
 }

 .demo__dot {
   width: 6px;
   height: 6px;
   border-radius: 50%;
   background: var(--green);
   box-shadow: 0 0 0 3px color-mix(in srgb, var(--green) 14%, transparent);
 }

 .demo__transcript,
 .demo__live {
   padding: 22px;
 }

 .demo__thread {
   min-height: 280px;
 }

 .demo__exchange + .demo__exchange {
   margin-top: 22px;
 }

 .demo__msg {
   display: flex;
   gap: 12px;
 }

 .demo__msg + .demo__msg {
   margin-top: 18px;
 }

 .demo__msg--user {
   justify-content: flex-end;
 }

 .demo__msg--assistant {
   align-items: flex-start;
   transition:
     opacity 0.5s var(--ease-apple-out),
     transform 0.5s var(--ease-apple-out);
 }

 .demo__msg--assistant.is-pending {
   opacity: 0;
   transform: translateY(8px);
 }

 .demo__bubble {
   max-width: 78%;
   padding: 10px 14px;
   border: 1px solid var(--line);
   border-radius: 18px 18px 6px 18px;
   background: var(--surface-hover);
   font-size: 0.9375rem;
   line-height: 1.55;
   white-space: pre-wrap;
   overflow-wrap: anywhere;
 }

 .demo__msg-body {
   flex: 1;
   min-width: 0;
   display: flex;
   flex-direction: column;
   gap: 14px;
