   margin-top: 8px;
   color: var(--faint);
   font-size: 0.6875rem;
 }

 /* ---------------------------------------------------------------- */
 /* Steps                                                            */
 /* ---------------------------------------------------------------- */

 .steps {
   display: grid;
   gap: 20px;
   grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
   counter-reset: step;
 }

 .step {
   position: relative;
   display: flex;
   flex-direction: column;
   gap: 12px;
   padding: 26px;
   border: 1px solid var(--line);
   border-radius: var(--r-lg);
   background: var(--surface);
   counter-increment: step;
 }

 .step::before {
   content: counter(step, decimal-leading-zero);
   font-family: var(--mono);
   font-size: 0.6875rem;
   font-weight: 600;
   letter-spacing: 0.1em;
   color: var(--accent);
 }

 .step__title {
   font-size: 1.125rem;
   font-weight: 600;
   letter-spacing: -0.01em;
 }

 .step__body {
   color: var(--muted);
   font-size: 0.9375rem;
   line-height: 1.6;
 }

 /* ---------------------------------------------------------------- */
 /* Connectors                                                       */
 /* ---------------------------------------------------------------- */

 .connector-group + .connector-group {
   margin-top: 36px;
 }

 .connector-list {
   display: grid;
   gap: 12px;
   grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
 }

 .connector {
   display: flex;
   flex-direction: column;
   gap: 8px;
   padding: 18px 20px;
   border: 1px solid var(--line);
   border-radius: var(--r-md);
   background: var(--surface);
   transition:
