@asynccontextmanager
async def lifespan(app: FastAPI):
    """Initialize and shut down the process-wide PostHog client."""
    settings = get_settings()
    posthog_client = build_client(settings)
    posthog_log_provider = None

    if posthog_client is not None:
        if not is_pytest():
            posthog_log_provider = configure_posthog_log_export(
                settings.posthog_api_key or "", settings.posthog_host or ""
            )
        atexit.register(posthog_client.shutdown)
    elif settings.debug and settings.posthog_enabled:
        missing_var = "POSTHOG_API_KEY" if not settings.posthog_api_key else "POSTHOG_HOST"
        raise RuntimeError(
            f"{missing_var} variable required by PostHog is missing or un-configured, "
            f"this causes events to be silently missed. This error stops appearing once "
            f"{missing_var} is configured"
        )

    app.state.posthog_client = posthog_client
    yield

    if posthog_client:
        posthog_client.shutdown()
    if posthog_log_provider:
        posthog_log_provider.shutdown()

"""Tests for the PostHog analytics integration in the Living Studio sidecar."""

from __future__ import annotations

import re
import uuid

import pytest
from agentic_odi_studio_api.config import Settings
from agentic_odi_studio_api.posthog_analytics import (
    build_client,
    capture,
    is_pytest,
    resolve_distinct_id,
)

HOST = "https://eu.i.posthog.com"


class _FakeRequest:
    """The sliver of a Starlette request the analytics layer reads."""

    def __init__(self, headers: dict[str, str] | None = None) -> None:
        self.headers = headers or {}


class _FakeClient:
    """Records what the analytics layer would have sent."""

    def __init__(self) -> None:
        self.events: list[dict] = []
        self.exceptions: list[Exception] = []
        self.shutdown_calls = 0

    def capture(self, event: str, **kwargs) -> None:
        self.events.append({"event": event, **kwargs})

    def capture_exception(self, exc: Exception, **kwargs) -> None:
        self.exceptions.append(exc)

    def shutdown(self) -> None:
        self.shutdown_calls += 1


def _settings(**overrides) -> Settings:
    """Build settings that never read the developer's ``.env``."""
    return Settings(_env_file=None, **overrides)

def resolve_distinct_id(request: HeaderSource | None = None, fallback: str | None = None) -> str:
    """Return the id an event should be attributed to.

    A request may name its own id — that is how a browser hands its anonymous
    id to the backend. Otherwise the install's device id is used, so one
    machine is one person in PostHog. A machine whose home directory cannot
    hold that id still gets a random id instead of failing the request.
    """
    if request is not None:
        header_id = request.headers.get(POSTHOG_DISTINCT_ID_HEADER)
        if header_id:
            return header_id
    if fallback is not None:
        return fallback
    try:
        return resolve_device_id()
    except OSError:
        return uuid.uuid4().hex

